      "tier": "Menengah",
      "level": "B1",
      "minutes": "4 menit",
      "text": "Living in a boarding house is fun but money runs out fast. (1) First, cook twice a week to save money. (2) For instance, instant noodles plus eggs cost only 10k. (3) Moreover, use public transport instead of ojek daily. (4) A monthly bus pass is much cheaper than daily rides. (5) Unless you track spending, you will panic at month-end. (6) If you save 200k monthly, you will have emergency cash. (7) You should also share WiFi costs with roommates. (8) Don't buy coffee daily if you can brew it. (9) Invite friends to cook together so it is cheaper and fun. (10) Record every expense in a small notebook. (11) Therefore, small habits matter more than big salary. (12) Start this week and feel the difference! (13)",
