      "title": "HP di Kelas: Larang atau Atur?",
      "tier": "Menengah",
      "level": "B1",
      "minutes": "4 menit",
      "text": "Schools debate whether phones should be banned. (1) Supporters say phones distract students badly. (2) For example, many students scroll TikTok during lessons. (3) However, phones can help learning if used wisely. (4) Students who use dictionaries learn faster. (5) Unless rules are clear, chaos will continue. (6) If teachers guide usage, phones become tools not toys. (7) In my school, phones are collected then returned after class. (8) Teachers who support this say scores have improved. (9) Parents have been asked to monitor screen time at home. (10) Students are taught to take notes digitally twice a week. (11) If this system continues, discipline will improve further. (12) This system seems fair for everyone. (13)",
