      "text": "Floods hit Semarang last night after heavy rain. (1) Officials say 200 houses were damaged. (2) Residents were evacuated to two shelters. (3) While officers were distributing aid, more rain started. (4) If the rain continues, more areas will be flooded. (5) The mayor said he would visit shelters today. (6) He told reporters that aid had arrived from Jakarta. (7) Volunteers who bring boats are badly needed. (8) Donations can be sent to the command post. (9) The water has been rising since midnight and hasn't receded. (10) Schools that are near the river have been closed for two days. (11) Unless the pumps work tonight, the market will stay closed. (12) Stay calm and follow official instructions. (13)",
