      "tier": "Menengah",
      "level": "B2",
      "minutes": "5 menit",
      "text": "Nadiem sells coffee from his motorbike every morning. (1) He leaves home at 5 a.m. and parks near the station. (2) If it rains, he will move under the bridge. (3) He would expand if he had more capital, but he saves slowly. (4) Customers say his kopi tubruk is as strong as café coffee. (5) He must have served thousands of cups by now. (6) He told me he had started with only 500k. (7) The bike that carries his stall was his father's gift. (8) Unless prices rise sharply, he will keep prices low. (9) He has been waking at 4 a.m. for three years without complaint. (10) While he was brewing yesterday, a tourist offered partnership. (11) If he accepts, he will have opened two stalls by December. (12) His story shows small capital plus consistency wins. (13)",
